import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Research library","description":"","frontmatter":{},"headers":[],"relativePath":"research/index.md","filePath":"research/index.md","lastUpdated":1794433168000}'),n={name:"research/index.md"};function s(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="research-library" tabindex="-1">Research library <a class="header-anchor" href="#research-library" aria-label="Permalink to &quot;Research library&quot;">​</a></h1><p><span class="status-label">PRIMARY SOURCES CHECKED · NOVEMBER 5, 2026</span></p><p>Study existing approaches before fixing our specification. These resources were selected for their relevance to hybrid retrieval, AI-extracted knowledge, durable ingestion, and streaming interfaces. Each collection explains what a resource contributes and which design questions still need our own tests.</p><h2 id="choose-a-collection" tabindex="-1">Choose a collection <a class="header-anchor" href="#choose-a-collection" aria-label="Permalink to &quot;Choose a collection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Collection</th><th>Find here</th><th>Start with</th></tr></thead><tbody><tr><td><a href="/knowledge-lab/research/similar-projects">Similar projects</a></td><td>Eight systems and frameworks, teams, repositories, design overlap, and differences</td><td>LightRAG, Graphiti, LlamaIndex, Microsoft GraphRAG</td></tr><tr><td><a href="/knowledge-lab/research/implementation-resources">Implementation resources</a></td><td>Twelve concrete repositories and documentation paths grouped by subsystem</td><td>SQLite candidates, Docling, spaCy, Rust adapters, orchestration</td></tr><tr><td><a href="/knowledge-lab/research/concepts">Concept reading guide</a></td><td>Fourteen annotated explanations connected to our own architecture</td><td>BM25, ANN, RRF, entity linking, DAGs, SSE</td></tr><tr><td><a href="/knowledge-lab/research/recent-developments">Recent developments</a></td><td>Seven dated releases, research updates, and project changes</td><td>Dependency status, vector indexing, extraction, Rust workflows</td></tr></tbody></table><p>Use the site&#39;s search to find a project or term such as “entity resolution,” “DiskANN,” “Graphiti,” or “replay.” Each collection links to original project material and deeper explanations.</p><h2 id="a-useful-first-reading-session" tabindex="-1">A useful first reading session <a class="header-anchor" href="#a-useful-first-reading-session" aria-label="Permalink to &quot;A useful first reading session&quot;">​</a></h2><ol><li>Read our <a href="/knowledge-lab/architecture/overview">system overview</a> to identify the boundaries we are evaluating.</li><li>Study <a href="/knowledge-lab/research/similar-projects">similar projects</a> and record one useful idea and one important difference for each serious candidate.</li><li>Follow the <a href="/knowledge-lab/research/concepts">concept guide</a> for unfamiliar mechanisms.</li><li>Examine <a href="/knowledge-lab/research/implementation-resources">implementation resources</a> at the actual repository and release level.</li><li>Check <a href="/knowledge-lab/research/recent-developments">recent developments</a> for maintenance status, prerelease features, and changed assumptions.</li><li>Turn the comparison into a bounded <a href="/knowledge-lab/decisions/">decision record</a> and an observable <a href="/knowledge-lab/validation">validation question</a>.</li></ol><h2 id="research-questions-to-answer" tabindex="-1">Research questions to answer <a class="header-anchor" href="#research-questions-to-answer" aria-label="Permalink to &quot;Research questions to answer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Useful evidence</th></tr></thead><tbody><tr><td>Does a graph help our corpus?</td><td>Compare entity-to-passage retrieval and bounded relationship expansion with the same lexical/vector baseline.</td></tr><tr><td>Can SQLite serve our workload?</td><td>Check exact/ANN behavior, eligible filtering, update rate, memory, and concurrent ingestion.</td></tr><tr><td>Which extraction pipeline fits?</td><td>Inspect parser source fidelity, domain entity types, entity resolution, provenance, and correction paths.</td></tr><tr><td>Which workflow engine owns progression?</td><td>Compare recovery, dependency invalidation, cancellation, and backfills on the same document workflow.</td></tr><tr><td>What makes chat feel immediate?</td><td>Separate startup, first grounded text, steady rendering, cancellation, and reconnect behavior.</td></tr></tbody></table><h2 id="from-research-to-a-portfolio" tabindex="-1">From research to a portfolio <a class="header-anchor" href="#from-research-to-a-portfolio" aria-label="Permalink to &quot;From research to a portfolio&quot;">​</a></h2><p>Save the question, original sources, alternatives, decision, and a planned check. During construction, connect that decision to a real change. During testing, connect it to actual results and limitations. These records become credible case-study evidence for the career portfolio. The <a href="/knowledge-lab/course-roadmap">IS373 assignment roadmap</a> shows what belongs at each course milestone.</p><p>Release dates and document-update dates are labeled separately. Linked projects and their claims are reference material, not proof that our proposed system is faster or that a dependency satisfies our requirements.</p>',13)])])}const f=t(n,[["render",s]]);export{u as __pageData,f as default};
